def tr_rotate(grid, stop_near_block=False):
    out=[row[:] for row in grid]; h,w=len(grid),len(grid[0])
    for r in range(h-1):
      for c in range(w-1):
        if grid[r][c]==grid[r][c+1]==grid[r+1][c]==grid[r+1][c+1]==2:
          specs=[(-1,-1,2,-1),(-1,2,-1,-1),(2,-1,2,2),(2,2,-1,2)]
          # tuple marker offset, source-offset for rotated color
          for dr,dc,sr0,sc0 in specs:
            rr,cc=r+dr,c+dc; color=grid[r+sr0][c+sc0]
            step_r=-1 if dr<0 else 1; step_c=-1 if dc<0 else 1
            while 0<=rr<h and 0<=cc<w:
              out[rr][cc]=color
              nr,nc=rr+step_r,cc+step_c
              if stop_near_block and 0<=nr<h and 0<=nc<w and any(0<=nr+ar<h and 0<=nc+ac<w and grid[nr+ar][nc+ac]==2 for ar,ac in ((0,1),(1,0),(0,-1),(-1,0))):
                break
              rr,cc=nr,nc
    return out
