def tr_rotate_smart(grid):
    out=[row[:] for row in grid];h,w=len(grid),len(grid[0]);blocks=[]; marker_colors={}
    specs=[(-1,-1,2,-1),(-1,2,-1,-1),(2,-1,2,2),(2,2,-1,2)]
    for r in range(h-1):
      for c in range(w-1):
       if grid[r][c]==grid[r][c+1]==grid[r+1][c]==grid[r+1][c+1]==2:
        blocks.append((r,c))
        for dr,dc,sr0,sc0 in specs:
         marker_colors[(r+dr,c+dc)]=grid[r+sr0][c+sc0]
    # initial recolored markers and rays
    for r,c in blocks:
      for dr,dc,sr0,sc0 in specs:
       rr,cc=r+dr,c+dc;color=grid[r+sr0][c+sc0];step_r=-1 if dr<0 else 1;step_c=-1 if dc<0 else 1
       first=True
       while 0<=rr<h and 0<=cc<w:
        if not first and grid[rr][cc]!=0: break
        out[rr][cc]=color
        nr,nc=rr+step_r,cc+step_c
        # avoid advancing into a point beside an identically colored marker
        if any((nr+ar,nc+ac) in marker_colors and marker_colors[(nr+ar,nc+ac)]==color for ar,ac in ((0,1),(1,0),(0,-1),(-1,0))): break
        first=False;rr,cc=nr,nc
    return out
