    for r in range(h-1):
      for c in range(w-1):
       if grid[r][c]==grid[r][c+1]==grid[r+1][c]==grid[r+1][c+1]==2:
        blocks.append((r,c))
        for dr,dc,sr0,sc0 in specs: marker_out[(r+dr,c+dc)]=grid[r+sr0][c+sc0]
    two={(i,j) for i in range(h) for j in range(w) if grid[i][j]==2}
    for r,c in blocks:
      for dr,dc,sr0,sc0 in specs:
       rr,cc=r+dr,c+dc;color=grid[r+sr0][c+sc0];step_r=-1 if dr<0 else 1;step_c=-1 if dc<0 else 1;first=True
       while 0<=rr<h and 0<=cc<w:
        if not first and grid[rr][cc]!=0: break
        out[rr][cc]=color
        nr,nc=rr+step_r,cc+step_c
        if 0<=nr<h and 0<=nc<w:
         adj=[(nr+ar,nc+ac) for ar,ac in ((0,1),(1,0),(0,-1),(-1,0))]
