def transform_candidate(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); blocks=[]
    corners=[(-1,-1,2,-1),(-1,2,-1,-1),(2,-1,2,2),(2,2,-1,2)]
    for r in range(h-1):
      for c in range(w-1):
       if grid[r][c]==grid[r][c+1]==grid[r+1][c]==grid[r+1][c+1]==2: blocks.append((r,c))
    for r,c in blocks:
      for dr,dc,sr0,sc0 in corners:
       rr,cc=r+dr,c+dc;color=grid[r+sr0][c+sc0];step_r=-1 if dr<0 else 1;step_c=-1 if dc<0 else 1;first=True
       while 0<=rr<h and 0<=cc<w:
        if not first and grid[rr][cc]!=0: break
        out[rr][cc]=color
        nr,nc=rr+step_r,cc+step_c
        # Stop before a southwest ray wraps around the top-left corner of another 2x2 block.
        if step_r==1 and step_c==-1 and any((nr,nc)==(br,bc-1) and (rr,cc)==(br-1,bc) for br,bc in blocks if (br,bc)!=(r,c)):
         break
        rr,cc=nr,nc;first=False
    return out
